-- Node: ft-nonviable-mgmt (4 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Nonviable Pregnancy — Management Options","body":"**OB consultation** for definitive management plan.\n\nOptions for the stable patient should be individualized based on symptoms, diagnosis, preferences, access to follow-up, and local OB resources. [17, 18, 42]\n\n**If visible products in cervix:** Remove at bedside with ring forceps. Consider sending to pathology (especially in recurrent miscarriage).\n\n**Surgical management is MANDATORY** for patients with significant hemorrhage or hemodynamic instability.","citation":[17,18,42],"options":[{"label":"Expectant management","description":"50-80% complete within 7-10 days","next":"ft-expectant"},{"label":"Medical management","description":"Preferred when available: mifepristone 200 mg PO, then misoprostol 800 mcg vaginally 24h later; misoprostol-only remains an option","next":"ft-medical-miscarriage"},{"label":"Surgical management","description":"D&C — lowest rates of incomplete miscarriage and bleeding","next":"ft-surgical-miscarriage","urgency":"urgent"}],"summary":"Expectant, medical, or surgical management — when available, mifepristone 200 mg followed 24h later by misoprostol 800 mcg is more effective than misoprostol alone"}'::jsonb
WHERE id = 'ft-nonviable-mgmt' AND tree_id = 'first-trimester';

-- Node: ft-medical-miscarriage (5 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Medical Management — Mifepristone + Misoprostol","body":"**Preferred regimen when mifepristone is available:** mifepristone 200 mg PO, followed 24 hours later by [misoprostol](#/drug/misoprostol/miscarriage) 800 mcg intravaginally. This combination is more effective than misoprostol alone. [42]\n\n**If mifepristone is unavailable:** misoprostol 800 mcg intravaginally, with one repeat dose as needed, no earlier than 3 hours after the first dose and typically within 7 days if there is no response. [42]\n\n**Contraindications:**\n• Hemodynamic instability (needs surgical evacuation)\n• Septic abortion\n• Confirmed ectopic pregnancy\n\n**Counsel patient:** Expect significant cramping and bleeding. Return precautions for heavy bleeding, fever, or worsening pain. Arrange follow-up in 7-14 days with ultrasound or serial hCG to confirm complete passage.\n\n[Miscarriage Discharge Instructions](#/info/ft-miscarriage-discharge)","citation":[17,18,19,42],"next":"ft-rh-rhogam","treatment":{"firstLine":{"drug":"Mifepristone + Misoprostol","dose":"Mifepristone 200 mg PO, then misoprostol 800 mcg","route":"PO, then intravaginal","frequency":"Mifepristone once; misoprostol 24 hours later","duration":"One treatment course; repeat misoprostol dose as needed per OB protocol","notes":"Preferred when mifepristone is available. Expect cramping and bleeding. Confirm complete passage in 7-14 days."},"alternative":{"drug":"Misoprostol (buccal)","dose":"800 mcg","route":"Buccal (between cheek and gum)","frequency":"Single dose","duration":"One-time; hold 30 min then swallow remnants","notes":"Alternative if patient prefers non-vaginal route. Slightly lower efficacy than vaginal."},"monitoring":"OB follow-up in 7-14 days with ultrasound to confirm complete passage. Return to ED for soaking >1 pad/hour for 2+ hours, fever >100.4F, or severe pain."},"summary":"Preferred: mifepristone 200 mg PO then misoprostol 800 mcg vaginally 24h later; misoprostol-only is an alternative","skippable":true}'::jsonb
WHERE id = 'ft-medical-miscarriage' AND tree_id = 'first-trimester';

-- Node: ft-rh-rhogam (4 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Rh Status & Anti-D Immune Globulin","body":"**Rh(D)-negative and unsensitized patients:** apply the clinical scenario and current local OB policy.\n\n**Pregnancy loss or abortion <12 weeks:** ACOG 2024 suggests that routine Rh testing and RhIg prophylaxis can be forgone; RhIg may still be offered after shared decision-making. SMFM remains more cautious and supports testing/RhIg when feasible.\n\n**Do not use the <12-week pathway for:**\n• Ectopic pregnancy\n• Uterine aspiration, sharp curettage, or other uterine instrumentation\n• Abdominal trauma or other events with meaningful fetomaternal hemorrhage risk\n\nFor these situations, discuss/administer RhIg with OB according to local policy. **At ≥12 weeks after pregnancy loss or abortion, RhIg is recommended.**\n\n**If indicated:**\n• [Rh(D) Immune Globulin](#/drug/rh-immune-globulin/first trimester) 50 mcg IM within 72 hours when a first-trimester dose is appropriate\n• If 50 mcg is unavailable, 300 mcg can be substituted\n\nFor isolated threatened bleeding with a viable pregnancy, follow local OB guidance because the 2024 ACOG update specifically addresses abortion and pregnancy loss.","citation":[20,43,44],"next":"ft-dispo-miscarriage","treatment":{"firstLine":{"drug":"Rh(D) Immune Globulin (RhoGAM)","dose":"50 mcg (250 IU)","route":"IM","frequency":"Single dose","duration":"When indicated, within 72 hours of the qualifying event","notes":"Use when indicated after considering gestational age and clinical scenario. Only for Rh(D)-negative, unsensitized patients. Confirm negative antibody screen before administration."},"alternative":{"drug":"Rh(D) Immune Globulin (standard dose)","dose":"300 mcg (1500 IU)","route":"IM","frequency":"Single dose","duration":"One-time, within 72 hours","notes":"Use if 50 mcg dose unavailable. Standard dose provides adequate coverage for first trimester."},"monitoring":"Document Rh status, antibody screen, gestational age, clinical scenario, and shared decision/local OB rationale. Ensure OB aware for repeat dosing at 28 weeks if pregnancy continues."},"summary":"RhIg is not routine for pregnancy loss/abortion <12 weeks under ACOG 2024, but remains recommended at ≥12 weeks and relevant for ectopic/instrumentation or other higher-risk events","safetyLevel":"warning"}'::jsonb
WHERE id = 'ft-rh-rhogam' AND tree_id = 'first-trimester';

