-- Node: sports-vascular (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Open fracture / vascular compromise","body":"**Action checklist:**\n- Stop active bleeding (direct pressure, tourniquet for life-threatening hemorrhage)\n- Reduce gross deformity if pulse absent and orthopedics delayed (gentle longitudinal traction)\n- Cover open wound with sterile saline-soaked gauze\n- IV access, tetanus, and weight-based first-dose antibiotic as soon as possible\n  - **Gustilo I/II:** [cefazolin](#/drug/cefazolin/open-fracture) 2 g IV for gram-positive coverage\n  - **Gustilo III:** use the local orthopedic-trauma protocol; current options include ceftriaxone or piperacillin-tazobactam monotherapy\n  - **Soil, fecal, farm, or suspected clostridial contamination:** add anaerobic coverage (for example, metronidazole) or high-dose penicillin per local protocol\n  - Do **not** reflexively add an aminoglycoside; older EAST protocols differ from newer AAOS/AAST recommendations and local trauma policy should control\n- NPO, type & screen, plain films, advanced imaging if pulse not restored\n- Orthopedic surgery consult NOW; vascular surgery if pulse asymmetry persists","citation":[2,15,16],"next":"sports-disposition","safetyLevel":"critical"}'::jsonb
WHERE id = 'sports-vascular' AND tree_id = 'sports-injuries';

-- Node: sports-head-entry (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Concussion vs structural head injury","body":"Is there any sign of structural injury that mandates CT?\n\n**Concerning features:**\n- LOC >1 minute\n- Persistent confusion or amnesia >30 min\n- Severe or worsening headache\n- Repeated vomiting\n- Focal neurologic deficit\n- Seizure\n- High-energy mechanism\n- Anticoagulation / coagulopathy\n- Suspected skull fracture (basilar signs, palpable depression)","citation":[3],"options":[{"label":"Concerning features → CT head","next":"sports-ct-head"},{"label":"No concerning features → symptom assessment / concussion path","next":"sports-concussion"}],"skippable":false,"safetyLevel":"critical"}'::jsonb
