-- Node: sports-concussion (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Concussion — assessment and early activity","body":"[Concussion symptom checklist](#/info/sports-concussion-checklist) at presentation and again before discharge.\n\n**Discharge criteria (no CT indicated):**\n- GCS 15, normal neuro exam, symptoms improving\n- Reliable observer at home\n- Clear instructions to return for any neurologic decline\n\n**Early recovery:**\n- Use **relative rest for the first 24-48 hours**, not strict physical and cognitive rest until symptom-free\n- Begin symptom-limited daily activity within 24 hours as tolerated; light aerobic activity is encouraged when it does not substantially worsen symptoms\n\n**Return-to-sport (Amsterdam 2022):** six steps, with **at least 24 hours at each step**. A mild, brief symptom increase (no more than 2/10 and resolving within 1 hour) can be tolerated; if symptoms are more severe or persist, reduce activity and return to the prior tolerated step.\n- Step 1: symptom-limited activity\n- Step 2: light, then moderate aerobic exercise\n- Step 3: individual sport-specific exercise, no head-impact risk\n- Step 4: non-contact training drills\n- Step 5: full-contact practice\n- Step 6: return to sport\n\nA clinician familiar with concussion management should clear progression into stages with head-impact risk. No same-day return to sport.[5]","citation":[3,5],"next":"sports-disposition","safetyLevel":"warning"}'::jsonb
WHERE id = 'sports-concussion' AND tree_id = 'sports-injuries';

-- Node: sports-disposition (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":7,"title":"Disposition and follow-up","body":"**ED pearls:**\n- Splint or sling for comfort, NSAIDs, ice, elevation\n- Crutches if NWB\n- Ortho or sports medicine follow-up — concussions ideally to a concussion clinic\n- Strict return precautions (worsening pain, neurovascular changes, fever, increased swelling)\n- Discuss timeline expectations — sports injuries rarely resolve in days\n\nFor concussion specifically, discharge instructions should include relative rest for 24-48 hours, early symptom-limited activity, no same-day return to sport, and no return to contact or collision risk until the six-step progression is complete and the patient has clinician clearance for the relevant stages.[5]","citation":[5],"next":"sports-rtp-checklist","safetyLevel":"warning"}'::jsonb
WHERE id = 'sports-disposition' AND tree_id = 'sports-injuries';

-- Node: sports-summary (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":7,"title":"Summary card","body":"**Sports injury workup at a glance:**\n\n- **Triage red flags first:** head, c-spine, vascular, dislocation\n- **Decision rules** save imaging: Ottawa Knee, Ottawa Ankle, NEXUS, Canadian C-Spine\n- **Concussion** → relative rest 24-48h, early symptom-limited activity, then six-step RTP with no same-day return\n- **Knee + ACL** → Lachman is most sensitive; Segond = ACL\n- **Maisonneuve** → palpate proximal fibula on every ankle\n- **Pediatric:** physes fail before ligaments → Salter-Harris until proven otherwise\n- **Female adolescent athlete + stress fracture** → screen for the Triad\n- **Disposition:** splint/sling, NSAIDs, ice, elevation, ortho/sports med follow-up, strict return precautions","citation":[5,9,11,13],"safetyLevel":"warning"}'::jsonb
WHERE id = 'sports-summary' AND tree_id = 'sports-injuries';

