-- Node: tox-alc-dialysis (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Hemodialysis Indications","body":"**EXTRIP guidelines for hemodialysis [1][4]:**\n\n**METHANOL — Dialysis recommended if:**\n• Methanol >70 mg/dL (or >50 mg/dL with severe acidosis)\n• Vision changes\n• Coma or seizures\n• Renal dysfunction\n• Severe metabolic acidosis despite treatment\n\n**ETHYLENE GLYCOL — use the newest EXTRIP criteria:**\n• **Recommend ECTR if glycolate >12 mmol/L or anion gap >27 mmol/L** when there is credible EG exposure\n• **Suggest ECTR if glycolate is 8-12 mmol/L or anion gap is 23-27 mmol/L**\n• **Recommend ECTR for coma, seizures, or KDIGO stage 2-3 AKI**, regardless of the parent EG level\n• EG >310 mg/dL remains a valid concentration trigger when fomepizole is being used, but do not wait for an EG level when glycolate, anion gap, or severe clinical features meet criteria\n\n**ISOPROPANOL:**\n• Generally NOT indicated (acetone not toxic)\n• Consider only if: persistent hypotension, serum level >500 mg/dL\n\n**Dialysis modality:**\n• Intermittent HD preferred (more efficient)\n• CRRT acceptable if hemodynamically unstable\n• Use high-flux, large surface area dialyzer\n\nDoes the patient meet dialysis criteria?","citation":[1,4,7],"options":[{"label":"Yes — meets dialysis criteria","description":"Consult nephrology urgently","next":"tox-alc-dialysis-info","urgency":"critical"},{"label":"No — fomepizole alone may suffice","description":"Continue fomepizole, close monitoring","next":"tox-alc-cofactors"},{"label":"Borderline — unsure","description":"Consult toxicology and/or nephrology","next":"tox-alc-dialysis-info","urgency":"urgent"}],"calculatorLinks":[{"id":"tox-alc-dialysis-criteria","label":"Dialysis Criteria"}],"summary":"HD for methanol >50-70 mg/dL or vision/coma; EG: glycolate/anion-gap or severe-feature criteria plus EG level; isopropanol rarely needs HD","safetyLevel":"warning"}'::jsonb
WHERE id = 'tox-alc-dialysis' AND tree_id = 'toxic-alcohols';

